// Fagulho: Lendas do Bosque — assets.js
// Dois sprites embutidos em base64 (o jogo é um site estático de arquivos
// soltos: nada de fetch, nada de pasta de imagens):
//   * heitorHead (68x96) — rosto real do Heitor, recortado da foto com fade
//     no pescoço; o corpo é desenhado pelo player.js.
//   * bossDragon (640x444) — o Dragão de Três Cabeças, o chefão. Recortado do
//     fundo ciano do original e virado para a esquerda, que é de onde o
//     jogador chega. As coordenadas notáveis do sprite (bocas, ponto fraco,
//     eixo da reverência) vivem no enemies.js, junto de quem as usa.
window.FG = window.FG || {};

(function () {
  var URI = 'data:image/png;base64,';
  var img;
  if (typeof Image !== 'undefined') {
    img = new Image();
    img.src = URI;
  } else {
    // ambiente sem DOM (testes headless): objeto inerte, nunca "carrega"
    img = { complete: false, naturalWidth: 0, naturalHeight: 0 };
  }
  var DRAGON_URI = 'data:image/png;base64,';
  var dragon;
  if (typeof Image !== 'undefined') {
    dragon = new Image();
    dragon.src = DRAGON_URI;
  } else {
    dragon = { complete: false, naturalWidth: 0, naturalHeight: 0 };
  }

  FG.assets = {
    heitorHead: img,
    headRatio: 68 / 96,
    // As medidas do dragão (640x444) e os pontos notáveis dentro dele vivem no
    // enemies.js, num bloco só: são coordenadas DESTA imagem, e trocar o sprite
    // é mexer nos dois lugares de uma vez.
    bossDragon: dragon,
  };
})();
